mapper.select:
SELECT (SELECT COUNT(*) FROM utb_app_mst WHERE create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND del_yn = 'N'
) AS total, (SELECT COUNT(*) FROM utb_app_mst WHERE create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND del_yn = 'N'
) AS newRequest, (SELECT COUNT(*) FROM utb_app_mst WHERE update_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND update_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND create_at != update_at AND del_yn = 'N'
) AS modifiedRequest, (SELECT COUNT(*) FROM utb_app_mst WHERE create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND app_classification = '10' AND del_yn = 'N'
) AS domesticAccept, (SELECT COUNT(*) FROM utb_app_mst WHERE create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND app_classification != '10' AND del_yn = 'N'
) AS overseasAccept, (SELECT COUNT(*) FROM utb_app_mst WHERE state = '10' AND create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND del_yn = 'N'
) AS inProgress, (SELECT COUNT(*) FROM utb_app_mst WHERE state = '20' AND create_at >= TO_TIMESTAMP(#{startDate}, 'YYYY-MM-DD') AND create_at <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS') AND del_yn = 'N'
) AS completed

WITH months AS (
    SELECT 1 AS month UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL
    SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL
    SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
)
SELECT
    CONCAT(T.month, '월') AS month,
    (SELECT COUNT(*) FROM utb_app_mst
     WHERE EXTRACT(MONTH FROM create_at) = T.month
       AND EXTRACT(YEAR FROM create_at) = #{year}
       AND del_yn = 'N'
       AND office_seq = #{officeSeq}
    ) AS newRequest,
    (SELECT COUNT(*) FROM utb_app_mst
     WHERE EXTRACT(MONTH FROM create_at) = T.month
       AND EXTRACT(YEAR FROM create_at) = #{year}
       AND app_classification = '10'
       AND del_yn = 'N'
       AND office_seq = #{officeSeq}
    ) AS domesticAccept,
    (SELECT COUNT(*) FROM utb_app_mst
     WHERE EXTRACT(MONTH FROM create_at) = T.month
       AND EXTRACT(YEAR FROM create_at) = #{year}
       AND app_classification != '10'
       AND del_yn = 'N'
       AND office_seq = #{officeSeq}
    ) AS overseasAccept,
    (SELECT COUNT(*) FROM utb_app_mst
     WHERE EXTRACT(MONTH FROM update_at) = T.month
       AND EXTRACT(YEAR FROM update_at) = #{year}
       AND create_at != update_at
       AND del_yn = 'N'
       AND office_seq = #{officeSeq}
    ) AS modifiedRequest,
    (SELECT COUNT(*) FROM utb_app_mst
     WHERE EXTRACT(MONTH FROM create_at) = T.month
       AND EXTRACT(YEAR FROM create_at) = #{year}
       AND fn_get_cd_nm('APP_STATE', app_state) = '조사의뢰'
       AND del_yn = 'N'
       AND office_seq = #{officeSeq}
    ) AS searchRequest
FROM months T
ORDER BY T.month
